import{_ as o,o as t,c as r,ag as s}from"./chunks/framework.8tqBsFWt.js";const _=JSON.parse('{"title":"User Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/users.md","filePath":"reference/tools/users.md"}'),a={name:"reference/tools/users.md"};function n(i,e,d,c,l,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="user-tools" tabindex="-1">User Tools <a class="header-anchor" href="#user-tools" aria-label="Permalink to &quot;User Tools&quot;">​</a></h1><hr><h2 id="add_user" tabindex="-1">add_user <a class="header-anchor" href="#add_user" aria-label="Permalink to &quot;add_user {#add_user}&quot;">​</a></h2><p>Create a new team member. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>03. Users</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>user_name</code></td><td>✅</td><td>Display name or Slack mention (see below)</td></tr><tr><td><code>role</code></td><td>✅</td><td><code>&quot;owner&quot;</code> | <code>&quot;manager&quot;</code> | <code>&quot;user&quot;</code></td></tr><tr><td><code>slack_user_id</code></td><td></td><td>Optional. Omit for contractors and vendors who are not yet in the Slack workspace. Can be added later via <code>update_user_role</code>.</td></tr><tr><td><code>discipline_id</code></td><td></td><td>FK → <code>08. Disciplines.id</code></td></tr><tr><td><code>employment_type</code></td><td></td><td><code>&quot;fte&quot;</code> (default) | <code>&quot;contractor&quot;</code> | <code>&quot;vendor&quot;</code></td></tr><tr><td><code>hours_per_week</code></td><td></td><td>Float. Working hours per week. <strong>FTE</strong>: omit — defaults to 40. <strong>Contractor</strong>: required — VERA will ask if not provided. <strong>Vendor</strong>: omit — defaults to 40 (not used for capacity).</td></tr></tbody></table><p><strong>Slack mention auto-resolution:</strong> If <code>user_name</code> is passed as a Slack mention token (<code>&lt;@U…&gt;</code>, bare <code>U…</code>/<code>W…</code>, <code>@handle</code>, markdown profile link, or email mention), VERA extracts the Slack user ID and fetches the real name from the Slack profile API (<code>real_name</code> → <code>display_name</code> fallback chain). The stored row will have the human-readable profile name, not the mention literal. If a <code>slack_user_id</code> is provided alongside <code>user_name</code>, the Slack profile name from the API overwrites the typed shortname. If the Slack API is unavailable and <code>user_name</code> is still a mention literal after resolution, the call is rejected with a descriptive error rather than storing garbage data.</p><hr><h2 id="list_users" tabindex="-1">list_users <a class="header-anchor" href="#list_users" aria-label="Permalink to &quot;list_users {#list_users}&quot;">​</a></h2><p>All active users with disciplines.</p><p><strong>Reads from</strong>: <code>03. Users</code>, <code>08. Disciplines</code></p><p>Inactive users appear with <code>(inactive)</code> next to their name.</p><hr><h2 id="update_user_role" tabindex="-1">update_user_role <a class="header-anchor" href="#update_user_role" aria-label="Permalink to &quot;update_user_role {#update_user_role}&quot;">​</a></h2><p>Change a user&#39;s permission role and other profile fields. <strong>Owner only.</strong> At least one of <code>new_role</code>, <code>new_slack_user_id</code>, <code>new_employment_type</code>, <code>new_email</code>, or <code>new_discipline_id</code> must be supplied.</p><p><strong>Updates</strong>: <code>03. Users</code> (role, slack id, employment type, email, and/or discipline)</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>user_name</code> or <code>slack_user_id</code>, and one or more of: <code>new_role</code>, <code>new_slack_user_id</code>, <code>new_employment_type</code>, <code>new_email</code>, <code>new_discipline_id</code>.</p><p><code>new_discipline_id</code> assigns the user&#39;s discipline; pass an empty string to clear it. A non-empty value must be the id of an <strong>active</strong> discipline. (Surfaced in the console Users page Edit modal as the &quot;Discipline&quot; selector.)</p><hr><h2 id="rename_user" tabindex="-1">rename_user <a class="header-anchor" href="#rename_user" aria-label="Permalink to &quot;rename_user {#rename_user}&quot;">​</a></h2><p>Change a user&#39;s display name. <strong>Owner only.</strong></p><p><strong>Updates</strong>: <code>03. Users</code> col C</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>current_name</code> or <code>slack_user_id</code>, <code>new_name</code></p><p><strong>Broken-row repair:</strong> If <code>slack_user_id</code> is supplied and the ID is not found in VERA by its stored <code>slack_user_id</code>, VERA checks for a row whose stored name is the raw mention literal (<code>&lt;@U…&gt;</code> or bare ID). If found, it renames the row and links the Slack ID in the same operation. This recovers users that were added before mention normalisation was in place.</p><hr><h2 id="assign_pm" tabindex="-1">assign_pm <a class="header-anchor" href="#assign_pm" aria-label="Permalink to &quot;assign_pm {#assign_pm}&quot;">​</a></h2><p>Assign a project manager to a project. <strong>Owner only.</strong></p><p>This is a two-in-one operation:</p><ol><li>Promotes the user to <code>manager</code> role (if currently <code>user</code>)</li><li>Sets <code>pm_user_id</code> on the project</li></ol><p><strong>Updates</strong>: <code>02. Projects</code> col G, <code>03. Users</code> col D</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>project_name</code>, <code>pm_name</code> or <code>pm_slack_id</code></p><blockquote><p>If the user hasn&#39;t messaged the bot yet, they won&#39;t be in the system. They need to send at least one message to be auto-registered before they can be assigned as PM.</p></blockquote><hr><h2 id="deactivate_user" tabindex="-1">deactivate_user <a class="header-anchor" href="#deactivate_user" aria-label="Permalink to &quot;deactivate_user {#deactivate_user}&quot;">​</a></h2><p>Mark a user as inactive. They cannot log time or take any actions. Historical entries are preserved. <strong>Owner only.</strong></p><p><strong>Updates</strong>: <code>03. Users</code> col E (status → <code>&quot;inactive&quot;</code>)</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>user_name</code> or <code>slack_user_id</code></p><p>Natural language triggers: &quot;delete user&quot;, &quot;remove user&quot;, &quot;deactivate user&quot; — all map to this tool.</p><hr><h2 id="reactivate_user" tabindex="-1">reactivate_user <a class="header-anchor" href="#reactivate_user" aria-label="Permalink to &quot;reactivate_user {#reactivate_user}&quot;">​</a></h2><p>Restore an inactive user. <strong>Owner only.</strong></p><p><strong>Updates</strong>: <code>03. Users</code> col E (status → <code>&quot;active&quot;</code>)</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>user_name</code> or <code>slack_user_id</code></p><p>Natural language triggers: &quot;reactivate&quot;, &quot;restore&quot;, &quot;re-enable&quot;</p><hr><h2 id="ensure_user" tabindex="-1">ensure_user <a class="header-anchor" href="#ensure_user" aria-label="Permalink to &quot;ensure_user {#ensure_user}&quot;">​</a></h2><p>Internal tool — auto-creates a user record if one doesn&#39;t exist for the given Slack ID. Called automatically when a new person messages the bot. Creates with <code>role = &quot;user&quot;</code> and <code>employment_type = &quot;fte&quot;</code>.</p><p><strong>Display name auto-sync</strong>: On every message, VERA compares the caller&#39;s current Slack display name to the stored name. If they differ (e.g. after a Slack workspace rename), the stored name is silently updated. Manual renames via <code>rename_user</code> are only needed if you want a name different from what appears in Slack.</p><hr><h2 id="list_disciplines" tabindex="-1">list_disciplines <a class="header-anchor" href="#list_disciplines" aria-label="Permalink to &quot;list_disciplines {#list_disciplines}&quot;">​</a></h2><p>All functional discipline categories.</p><p><strong>Reads from</strong>: <code>08. Disciplines</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code></p><hr><h2 id="add_discipline" tabindex="-1">add_discipline <a class="header-anchor" href="#add_discipline" aria-label="Permalink to &quot;add_discipline {#add_discipline}&quot;">​</a></h2><p>Create a new functional discipline category. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>08. Disciplines</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>name</code></p><blockquote><p>The words &quot;Designer,&quot; &quot;Developer,&quot; &quot;Project Manager&quot; may refer to a person name or a discipline. VERA confirms before acting when the context is ambiguous.</p></blockquote><hr><h2 id="rename_discipline" tabindex="-1">rename_discipline <a class="header-anchor" href="#rename_discipline" aria-label="Permalink to &quot;rename_discipline {#rename_discipline}&quot;">​</a></h2><p>Rename an existing discipline category. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>08. Disciplines</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>old_name</code>, <code>new_name</code></p><blockquote><p>Blocks case-insensitive name collisions. No user records need updating — disciplines are referenced by ID.</p></blockquote><p><strong>Returns</strong>: <code>discipline_id</code>, <code>old_name</code>, <code>new_name</code></p><hr><h2 id="archive_discipline" tabindex="-1">archive_discipline <a class="header-anchor" href="#archive_discipline" aria-label="Permalink to &quot;archive_discipline {#archive_discipline}&quot;">​</a></h2><p>Archive a discipline category so it no longer appears in menus. <strong>Owner only.</strong> Historical references are preserved. Use <code>unarchive_discipline</code> to restore.</p><p><strong>Writes to</strong>: <code>08. Disciplines</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>discipline_name</code></p><blockquote><p>Hard fails (409) if any active user has this discipline assigned. Reassign all users&#39; discipline field first.</p></blockquote><p><strong>Returns</strong>: <code>discipline_id</code>, <code>discipline_name</code></p><hr><h2 id="unarchive_discipline" tabindex="-1">unarchive_discipline <a class="header-anchor" href="#unarchive_discipline" aria-label="Permalink to &quot;unarchive_discipline {#unarchive_discipline}&quot;">​</a></h2><p>Restore an archived discipline so it appears in menus again. <strong>Owner only.</strong></p><p><strong>Writes to</strong>: <code>08. Disciplines</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>discipline_name</code></p><p><strong>Returns</strong>: <code>discipline_id</code>, <code>discipline_name</code></p><hr><h2 id="get_project_assignments" tabindex="-1">get_project_assignments <a class="header-anchor" href="#get_project_assignments" aria-label="Permalink to &quot;get_project_assignments {#get_project_assignments}&quot;">​</a></h2><p>Who is allocated to a project. <strong>Manager/Owner.</strong></p><p>Shared with <a href="/reference/tools/allocations.html#get_project_assignments">Envelope Tools</a> — documented there.</p>',84)])])}const h=o(a,[["render",n]]);export{_ as __pageData,h as default};
